    for k in range(n*n, 0, -1):
        r = n*n - k
        pairs = []
        for i in range(n):
            for j in range(n):
                if j + 1 < n:
                    pairs.append(((i, j), (i, j+1)))
                if i + 1 < n:
                    pairs.append(((i, j), (i+1, j)))

        for combo in itertools.combinations(pairs, r):
            squares = []
            for p1, p2 in combo:
                squares.extend([p1, p2])
            if len(set(squares)) == 2*r:
                covered_blocks = set()
                for p1, p2 in combo:
                    if p1[0] == p2[0]:
                        i, j = p1[0], p1[1]
                        if i > 0: covered_blocks.add((i-1, j))
                        if i < n-1: covered_blocks.add((i, j))
                    else:
                        i, j = p1[0], p1[1]
                        if j > 0: covered_blocks.add((i, j-1))
                        if j < n-1: covered_blocks.add((i, j))
                if len(covered_blocks) == (n-1)**2:
                    return k
    return 0

