    pair_covers = []
    for p in pairs:
        covered = set()
        if p[0][0] == p[1][0]: # Horizontal
            i, j = p[0][0], p[0][1]
            if i > 0: covered.add((i-1, j))
            if i < n-1: covered.add((i, j))
        else: # Vertical
            i, j = p[0][0], p[0][1]
            if j > 0: covered.add((i, j-1))
            if j < n-1: covered.add((i, j))
        pair_covers.append(covered)

    # Now find the minimum r such that there exist r disjoint pairs whose coverage is num_blocks.
    for r in range((n-1)**2 // 2, (n-1)**2 + 1):
        for combo in itertools.combinations(range(len(pairs)), r):
            # Check if disjoint
            squares = []
            for idx in combo:
                squares.extend(pairs[idx])
            if len(set(squares)) == 2*r:
                # Check if covers all blocks
                covered_all = set()
                for idx in combo:
                    covered_all.update(pair_covers[idx])
                if len(covered_all) == num_blocks:
                    return r
    return None

